#include <stdio.h>
#include <openssl/bn.h>

void printBN(char *msg, BIGNUM * a)
{
    char * number_str = BN_bn2hex(a);
    printf("%s %s\n", msg, number_str);
    OPENSSL_free(number_str);
} 

int main() {
    
    //Initialization of BIGNUM variables
    BN_CTX *ctx = BN_CTX_new();
    BIGNUM *MD = BN_new();
    BIGNUM *d = BN_new();
    BIGNUM *e = BN_new();
    BIGNUM *n = BN_new();
    BIGNUM *s = BN_new();
    BIGNUM *S_DECRYPTED = BN_new();

    //Assigning values to a BIGNUM variable
    BN_hex2bn(&n, "");
    BN_hex2bn(&e, "10001");
    BN_hex2bn(&s, "");

    // calculate MD_DECRYPTED
    BN_mod_exp(S_DECRYPTED, s, e, n, ctx);
    // print result
    printBN("Sign decrypted = ", S_DECRYPTED);

    return 0;
}

